/* ======================= utilidades ======================= */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
/* Acepta números escritos al estilo venezolano: 1.051,25 o 1051,25 o 1051.25 */
const num = v => {
  let s = String(v ?? "").replace(/\s/g, "");
  if (s.includes(",")) s = s.replace(/\./g, "").replace(",", ".");
  else if ((s.match(/\./g) || []).length > 1) s = s.replace(/\./g, "");
  const n = parseFloat(s); return isFinite(n) ? n : 0;
};
const r2 = n => Math.round((Number(n) || 0) * 100) / 100;
const money = n => "€ " + (Number(n) || 0).toLocaleString("es-VE", {minimumFractionDigits: 2, maximumFractionDigits: 2});
const bs = n => "Bs " + (Number(n) || 0).toLocaleString("es-VE", {minimumFractionDigits: 2, maximumFractionDigits: 2});
const tasa = () => num(S.tasa?.valor);
const tasaUsd = () => num(S.tasa?.usd);
const usd = n => "$ " + (Number(n) || 0).toLocaleString("es-VE", {minimumFractionDigits: 2, maximumFractionDigits: 2});
/* dólares que realmente obtienes por cada euro vendido: lo cobras en Bs a tasa euro y compras dólares a tu tasa del dólar */
const fx = () => (tasa() && tasaUsd()) ? tasa() / tasaUsd() : 1;
const enBs = n => tasa() ? bs(n * tasa()) : "";
const dias = f => f ? Math.max(0, Math.floor((Date.now() - new Date(f + "T12:00:00")) / 86400000)) : 0;
const uid = () => Math.random().toString(36).slice(2, 10);
const hoy = () => { const d = new Date(); return new Date(d - d.getTimezoneOffset()*60000).toISOString().slice(0,10); };
const mesActual = () => hoy().slice(0, 7);
const fecha = s => s ? new Date(s + "T12:00:00").toLocaleDateString("es-VE", {day:"2-digit", month:"short", year:"numeric"}) : "";
const blobUrl = id => id || ""; // en esta versión se guarda la dirección completa de Cloudinary
const pct = (precio, costo) => { const pu = precio * fx(); return costo > 0 ? ((pu - costo) / costo) * 100 : (pu > 0 ? 100 : 0); };

